void require(bool b,const char *m){if(!b)throw std::runtime_error(m);}
void ok(QString e){if(!e.isEmpty())throw std::runtime_error(e.toStdString());}
void close(double a,double b,const char *m){require(std::abs(a-b)<1e-7,m);}
DrawingSourceBody source(Body body,quint64 id=1){auto b=std::make_shared<Body>(std::move(body));return {id,b,std::make_shared<ElementNames>(propagateNames(*b,makeHistory({},*b),{},"f"+std::to_string(id)))};}
QByteArray bytes(const DrawingSheet &s){QByteArray b;ok(encodeDrawingSheet(s,b));return b;}
void mouse(DrawingSheetEditor &e,QPointF p,bool click=false,Qt::KeyboardModifiers modifiers=Qt::NoModifier){auto *v=e.canvas();const QPointF local=v->mapFromScene(p),global=v->viewport()->mapToGlobal(local.toPoint());QMouseEvent event(click?QEvent::MouseButtonPress:QEvent::MouseMove,local,global,click?Qt::LeftButton:Qt::NoButton,click?Qt::LeftButton:Qt::NoButton,modifiers);QApplication::sendEvent(v->viewport(),&event);if(click){QMouseEvent release(QEvent::MouseButtonRelease,local,global,Qt::LeftButton,Qt::NoButton,modifiers);QApplication::sendEvent(v->viewport(),&release);}}
void key(DrawingSheetEditor &e,int k){QKeyEvent event(QEvent::KeyPress,k,Qt::NoModifier);QApplication::sendEvent(e.canvas(),&event);}
const DrawingViewLayout &layout(const DrawingSheetEditor &e,QUuid id){for(const auto &l:e.sheet().views)if(l.viewId==id)return l;throw std::runtime_error("layout assente");}
const DrawingView &view(const DrawingSheetEditor &e,QUuid id){for(const auto &v:e.sheet().drawing.views)if(v.id==id)return v;throw std::runtime_error("view assente");}
int items(DrawingSheetEditor &e,QString kind){int n=0;for(auto *i:e.canvas()->scene()->items())n+=i->data(0).toString()==kind;return n;}
class Counted final:public Curve<3>{CurvePtr<3> curve_;std::shared_ptr<int> count_;public:Counted(CurvePtr<3> c,std::shared_ptr<int> n):curve_(std::move(c)),count_(std::move(n)){}CurveType type()const override{return CurveType::Other;}Interval domain()const override{return curve_->domain();}void evaluate(double t,int n,Vec3 *o)const override{++*count_;curve_->evaluate(t,n,o);}};
